# model 10x10 masks based on observed stamps
masks=[]
for k in range(5):
    s=set()
    for r in range(10):
        if k==0: cols=range(0,10-r)
        elif k==1: cols=range(5,10) if r<5 else range(5+(r-5),10)
        elif k==2: cols=range(9-r,10)
        elif k==3: cols=range(0,0) if r<5 else range(0,5-(r-5))
        elif k==4: cols=range(0,r+1)
        for c in cols:s.add(r*10+c)
    masks.append(s)
target={(r*10+c) for r in range(10) for c in (range(9-r,10) if r>=5 else [])}
from collections import deque
start=frozenset()
q=deque([start]); prev={start:None}; how={}
while q:
    st=q.popleft()
    if st==target:break
    for k,m in enumerate(masks):
        for color in [1,0]:
            ns=frozenset(set(st)|m if color else set(st)-m)
            if ns not in prev:
                prev[ns]=st;how[ns]=(k,color);q.append(ns)
print('reachable',target in prev,'states',len(prev))
if target in prev:
    path=[];cur=target
    while prev[cur] is not None:
        path.append(how[cur]);cur=prev[cur]
    print(path[::-1])

